local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "neiz404"
Junkie.identifier = "1036603"
Junkie.provider = "safelinku"

local CoreGui = game:GetService("CoreGui")
if CoreGui:FindFirstChild("Xyzrproxticolosis") then
    CoreGui.Xyzrproxticolosis:Destroy()
end

game:GetService("StarterGui"):SetCore("DevConsoleVisible", true)

print("........................................................................")
print(".                                                                      .")
print(".                     -- Xyzrproxticolosis Hub                         .")
print(".                                                                      .")
print(".           Discord   →   https://discord.gg/c9FgPfaDnn                .")
print(".           YouTube   →   https://www.youtube.com/@Neiz404             .")
print(".                                                                      .")
print("........................................................................")

setclipboard("Discord: https://discord.gg/c9FgPfaDnn\nYouTube: https://www.youtube.com/@Neiz404")

local result = (function()
getgenv().UI_CLOSED = false
local TweenService = game:GetService("TweenService")
local Lighting = game:GetService("Lighting")
local UserInputService = game:GetService("UserInputService")

local function fs()
    local w = pcall(function() return type(writefile) == "function" end)
    local r = pcall(function() return type(readfile) == "function" end)
    return w and r
end

local function saveKey(k)
    if fs() then pcall(function() writefile("xyz_auth.txt", k) end) end
end

local function loadKey()
    if fs() then
        local s, c = pcall(function() return readfile("xyz_auth.txt") end)
        if s then return c end
    end
    return nil
end

local UI = {}
UI.__index = UI

function UI.new()
    local self = setmetatable({}, UI)
    self.gui = Instance.new("ScreenGui")
    self.gui.Name = "Xyzrproxticolosis"
    self.gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    self.gui.ResetOnSpawn = false
    self.gui.Parent = CoreGui

    local blur = Instance.new("BlurEffect")
    blur.Size = 0
    blur.Parent = Lighting
    self.blur = blur
    TweenService:Create(blur, TweenInfo.new(0.6), {Size = 20}):Play()

    local main = Instance.new("Frame")
    main.Size = UDim2.new(0, 460, 0, 280)
    main.Position = UDim2.new(0.5, 0, 0.5, 0)
    main.AnchorPoint = Vector2.new(0.5, 0.5)
    main.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
    main.BackgroundTransparency = 0.3
    main.BorderSizePixel = 0
    main.ClipsDescendants = true
    main.Parent = self.gui

    local dragging, dragInput, dragStart, startPos
    main.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            dragStart = input.Position
            startPos = main.Position
        end
    end)
    main.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement then
            dragInput = input
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            local delta = input.Position - dragStart
            main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)

    Instance.new("UICorner", main).CornerRadius = UDim.new(0, 16)
    local stroke = Instance.new("UIStroke", main)
    stroke.Color = Color3.fromRGB(255, 255, 255)
    stroke.Thickness = 1.6
    stroke.Transparency = 0.5

    local title = Instance.new("TextLabel", main)
    title.Size = UDim2.new(1, 0, 0, 70)
    title.Text = "Xyzrproxticolosis Hub"
    title.TextColor3 = Color3.fromRGB(255, 255, 255)
    title.TextSize = 27
    title.Font = Enum.Font.GothamBold
    title.BackgroundTransparency = 1

    local box = Instance.new("TextBox", main)
    box.Size = UDim2.new(0.85, 0, 0, 52)
    box.Position = UDim2.new(0.5, 0, 0.45, 0)
    box.AnchorPoint = Vector2.new(0.5, 0.5)
    box.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
    box.BackgroundTransparency = 0.65
    box.Text = ""
    box.PlaceholderText = "Paste Your Key Here"
    box.PlaceholderColor3 = Color3.fromRGB(160, 160, 160)
    box.TextColor3 = Color3.fromRGB(255, 255, 255)
    box.Font = Enum.Font.GothamMedium
    box.TextSize = 16
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 12)
    self.box = box

    local btnContainer = Instance.new("Frame", main)
    btnContainer.Size = UDim2.new(0.85, 0, 0, 50)
    btnContainer.Position = UDim2.new(0.5, 0, 0.75, 0)
    btnContainer.AnchorPoint = Vector2.new(0.5, 0.5)
    btnContainer.BackgroundTransparency = 1

    local function createBtn(txt, pos, color, cb)
        local b = Instance.new("TextButton", btnContainer)
        b.Size = UDim2.new(0.45, 0, 1, 0)
        b.Position = pos
        b.BackgroundColor3 = color
        b.BackgroundTransparency = 0.7
        b.Text = txt
        b.TextColor3 = Color3.fromRGB(255, 255, 255)
        b.Font = Enum.Font.GothamBold
        b.TextSize = 15
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 12)
        b.MouseButton1Click:Connect(cb)
        return b
    end

    createBtn("GET KEY", UDim2.new(0, 0, 0, 0), Color3.fromRGB(40, 40, 40), function()
        local l = Junkie.get_key_link()
        if l then setclipboard(l) end
    end)

    createBtn("VERIFY", UDim2.new(0.55, 0, 0, 0), Color3.fromRGB(40, 40, 40), function()
        self:Verify()
    end)

    self.main = main
    return self
end

function UI:Verify()
    local k = self.box.Text:gsub("%s+", "")
    local success, res = pcall(function() return Junkie.check_key(k) end)
    
    if success and (res == true or (type(res) == "table" and res.valid)) then
        saveKey(k)
        getgenv().SCRIPT_KEY = k
        self:Destroy()
    else
        self.box.Text = ""
        self.box.PlaceholderText = "INVALID KEY"
        task.wait(1.5)
        self.box.PlaceholderText = "Paste access key here..."
    end
end

function UI:Destroy()
    getgenv().UI_CLOSED = true
    self.blur:Destroy()
    self.gui:Destroy()
end

local saved = loadKey()
local autoKey = saved or getgenv().SCRIPT_KEY

if autoKey then
    local s, r = pcall(function() return Junkie.check_key(autoKey) end)
    if s and (r == true or (type(r) == "table" and r.valid)) then
        getgenv().SCRIPT_KEY = autoKey
        getgenv().UI_CLOSED = true
        return autoKey
    end
end

local app = UI.new()
while not getgenv().UI_CLOSED do task.wait(0.1) end
return getgenv().SCRIPT_KEY
end)()

